const canvas=document.getElementById('stage'),ctx=canvas.getContext('2d');
const tooltip=document.getElementById('tooltip');let DPR=1,W=0,H=0,lastT=0,fps=60,lastFpsUpdate=0;
const camera={x:0,y:10,zoom:1.05,targetX:0,targetY:10,targetZoom:1.05};
const pointer={x:-999,y:-999,down:false,lastX:0,lastY:0,moved:false};
const QUALITY_VERSION='v5-readable';
try{if(localStorage.getItem('worldroadmap-quality-version')!==QUALITY_VERSION){localStorage.setItem('worldroadmap-quality','low');localStorage.setItem('worldroadmap-quality-version',QUALITY_VERSION)}}catch(_){}
let qualityMode=localStorage.getItem('worldroadmap-quality')||'low';
if(!['high','low'].includes(qualityMode)) qualityMode='low';
let active='All',query='',selected=null,hover=null,hoverCountry=null,densityMode=true,flowMode=false,labelsMode=true,perfMode=(qualityMode==='low');
const APP_VERSION='v5';
let currentTheme=localStorage.getItem('worldroadmap-theme')||'nebula';
applyTheme(currentTheme);
const COUNTRY_ALIASES={'United States of America':'United States'};const FEATURE_ALIASES={'United States':'United States of America'};
function dataCountryName(name){return COUNTRY_ALIASES[name]||name}
const countryStats=computeCountryStats();const maxCountry=Math.max(...countryStats.map(d=>d.models),1);
const countryFeatureMap=new Map(WORLD.features.map(f=>[f.name,f]));Object.entries(FEATURE_ALIASES).forEach(([dataName,featureName])=>{if(countryFeatureMap.has(featureName))countryFeatureMap.set(dataName,countryFeatureMap.get(featureName))});
const allModels=ORGS.flatMap(o=>o.models.map((m,i)=>({name:m,org:o.name,country:o.country,city:o.city,lat:o.lat,lng:o.lng,type:o.type,cat:o.cats[i%o.cats.length]||'General',tier:o.tier,hot:o.hot,orgId:o.id,index:i})));
const paperGroups=computePaperGroups();
const topOrgs=[...ORGS].sort((a,b)=>(b.hot||0)-(a.hot||0)||b.models.length-a.models.length).slice(0,24);
let clouds=makeCloudParticles();const flows=makeFlows();const stars=makeStars(520);
function seeded(n){let x=Math.sin(n*12.9898+78.233)*43758.5453;return x-Math.floor(x)}
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)}return Math.abs(h)}
function makeStars(n){const a=[];for(let i=0;i<n;i++)a.push({x:seeded(i+1),y:seeded(i+77),r:seeded(i+211)*1.4+.25,c:seeded(i+311),p:seeded(i+411)*6.28});return a}
function makeCloudParticles(){const out=[];ORGS.forEach((o,oi)=>{const base=18+o.models.length*16+(o.tier==='frontier'?44:0)+(o.type==='Open'?18:0);const n=Math.min(perfMode?150:260,Math.floor(base));for(let k=0;k<n;k++){const seed=hash(o.id+':'+k);const mi=Math.floor(seeded(seed+2)*o.models.length);const cat=o.cats[mi%o.cats.length]||'General';const angle=seeded(seed+3)*Math.PI*2;const radius=(8+Math.pow(seeded(seed+4),.55)*(58+o.models.length*8))*(seeded(seed+5)>.78?1.42:1);out.push({oi,mi,cat,angle,radius,phase:seeded(seed+6)*Math.PI*2,spin:(seeded(seed+7)-.5)*.0014,size:.55+seeded(seed+8)*1.8,shape:seeded(seed+9)>.92?'tri':(seeded(seed+10)>.96?'dash':'dot'),alpha:.22+seeded(seed+11)*.55})}});return out}
function makeFlows(){const names=['OpenAI','Anthropic','Google DeepMind','Meta AI','Hugging Face','Mistral AI','DeepSeek','Alibaba Qwen','Moonshot AI','MiniMax','Zhipu AI','Cohere','Technology Innovation Institute','Sakana AI','AI Singapore','Stability AI'];const base=names.map(n=>ORGS.find(o=>o.name.includes(n)||n.includes(o.name))).filter(Boolean);const out=[];for(let i=0;i<base.length;i++){for(let j=i+1;j<base.length;j++){if(out.length>34)break;const a=base[i],b=base[j];const score=(a.hot||70)+(b.hot||70)-Math.abs(a.lng-b.lng)*.12;if(score>115||seeded(hash(a.name+b.name))>.64)out.push({a,b,phase:seeded(hash(a.name+'>'+b.name)),color:categoryColor(a.cats[0],a.type)})}}return out}
function resize(){DPR=Math.max(1,Math.min(perfMode?1:1.35,window.devicePixelRatio||1));W=innerWidth;H=innerHeight;canvas.width=Math.round(W*DPR);canvas.height=Math.round(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';ctx.setTransform(DPR,0,0,DPR,0,0)}addEventListener('resize',resize);resize();
let pageVisible=!document.hidden;document.addEventListener('visibilitychange',()=>{pageVisible=!document.hidden;if(pageVisible){lastT=0;requestAnimationFrame(render)}});
function baseScale(){return Math.min(W/2.06,H/1.10)}
function project(lng,lat){const s=baseScale()*camera.zoom;const x=W/2+camera.x+(lng/180)*s*1.08;let y=H/2+camera.y-(lat/90)*s*.73;const curve=Math.sin((lng/180)*Math.PI)*Math.cos((lat/90)*Math.PI*.54)*s*.040;const polar=Math.pow(Math.abs(lat)/90,1.85)*s*.018;y+=curve+polar;return {x,y}}
function inverse(x,y){const s=baseScale()*camera.zoom;const lng=((x-W/2-camera.x)/(s*1.08))*180;const curve=Math.sin((lng/180)*Math.PI)*s*.040;const lat=-((y-H/2-camera.y-curve)/(s*.73))*90;return {lng:Math.max(-180,Math.min(180,lng)),lat:Math.max(-85,Math.min(85,lat))}}
function clampCamera(){const s=baseScale()*camera.targetZoom;camera.targetX=Math.max(-s*1.32,Math.min(s*1.32,camera.targetX));camera.targetY=Math.max(-s*.68,Math.min(s*.70,camera.targetY))}
function flyTo(lng,lat,zoom=2.35){const s=baseScale()*zoom;camera.targetZoom=zoom;camera.targetX=-(lng/180)*s*1.08;let curve=Math.sin((lng/180)*Math.PI)*s*.040;camera.targetY=(lat/90)*s*.73-curve;clampCamera()}
function smooth(){const k=perfMode?.135:.125;camera.x+=(camera.targetX-camera.x)*k;camera.y+=(camera.targetY-camera.y)*k;camera.zoom+=(camera.targetZoom-camera.zoom)*k}
function makePath(polygons){ctx.beginPath();for(const ring of polygons){for(let i=0;i<ring.length;i++){const p=project(ring[i][0],ring[i][1]);if(i===0)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y)}ctx.closePath()}}
function drawBackground(t){ctx.clearRect(0,0,W,H);const theme=THEMES[currentTheme]||THEMES.nebula;const stops=theme.canvas||THEMES.nebula.canvas;const g=ctx.createRadialGradient(W*.50,H*.42,0,W*.50,H*.42,Math.max(W,H)*.78);g.addColorStop(0,stops[0]);g.addColorStop(.34,stops[1]);g.addColorStop(1,stops[2]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.save();for(let si=0;si<stars.length;si++){if(perfMode&&si%3===0)continue;const s=stars[si];const tw=.45+Math.sin(t*.0012+s.p)*.35;ctx.globalAlpha=(s.c>.92?.85:.35)*tw;ctx.fillStyle=s.c>.84?'rgba(122,231,255,.95)':'rgba(255,255,255,.85)';const x=(s.x*W + camera.x*.012*s.r + W)%W;const y=(s.y*H + camera.y*.010*s.r + H)%H;ctx.beginPath();ctx.arc(x,y,s.r,0,Math.PI*2);ctx.fill()}ctx.restore();ctx.save();ctx.globalAlpha=.12;ctx.strokeStyle='rgba(125,223,255,.18)';ctx.lineWidth=1;const gap=Math.max(18,36*camera.zoom);for(let x=(W/2+camera.x*.22)%gap;x<W;x+=gap){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=(H/2+camera.y*.22)%gap;y<H;y+=gap){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.restore()}
function drawGraticule(){ctx.save();ctx.lineWidth=.75;ctx.strokeStyle='rgba(170,198,255,.11)';for(let lng=-180;lng<=180;lng+=20){ctx.beginPath();for(let lat=-70;lat<=82;lat+=4){const p=project(lng,lat);if(lat===-70)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y)}ctx.stroke()}for(let lat=-60;lat<=80;lat+=10){ctx.beginPath();for(let lng=-180;lng<=180;lng+=5){const p=project(lng,lat);if(lng===-180)ctx.moveTo(p.x,p.y);else ctx.lineTo(p.x,p.y)}ctx.stroke()}ctx.globalAlpha=.48;ctx.fillStyle='rgba(220,235,255,.55)';for(let lng=-170;lng<=170;lng+=10){for(let lat=-60;lat<=75;lat+=10){const p=project(lng,lat);ctx.fillRect(p.x-.8,p.y-.8,1.6,1.6)}}ctx.restore()}
function countryMetric(name){const dc=dataCountryName(name);const s=countryStats.find(x=>x.country===dc);return s?s.models:0}
function drawCountries(){ctx.save();ctx.translate(0,13*camera.zoom);ctx.fillStyle='rgba(3,8,20,.58)';ctx.strokeStyle='rgba(30,70,120,.15)';ctx.lineWidth=1.2;for(const f of WORLD.features){if(f.name==='Antarctica')continue;makePath(f.polygons);ctx.fill();ctx.stroke()}ctx.restore();ctx.save();ctx.globalCompositeOperation='source-over';for(const f of WORLD.features){if(f.name==='Antarctica')continue;const metric=countryMetric(f.name);const isHover=hoverCountry&&hoverCountry.name===f.name;const isSelected=selected&&selected.kind==='country'&&selected.data.country===dataCountryName(f.name);makePath(f.polygons);const alpha=metric?Math.min(.31,.07+metric/maxCountry*.30):.048;ctx.fillStyle=isSelected?'rgba(255,186,116,.25)':isHover?'rgba(104,233,255,.18)':`rgba(52,80,118,${alpha})`;ctx.fill();ctx.lineWidth=isHover||isSelected?1.7:.82;ctx.strokeStyle=isSelected?'rgba(255,218,160,.90)':isHover?'rgba(104,233,255,.78)':'rgba(204,226,255,.24)';ctx.shadowColor=isSelected?'rgba(255,186,116,.8)':'rgba(104,233,255,.24)';ctx.shadowBlur=isHover||isSelected?18:6;ctx.stroke();ctx.shadowBlur=0;if(metric>0&&camera.zoom>1.9){const p=project(f.center[0],f.center[1]);ctx.fillStyle='rgba(235,242,255,.82)';ctx.font='800 10px Inter,Arial';ctx.textAlign='center';ctx.fillText(CJK_COUNTRY[dataCountryName(f.name)]||dataCountryName(f.name),p.x,p.y)}}ctx.restore()}
function drawDensity(t){if(!densityMode)return;ctx.save();ctx.globalCompositeOperation='lighter';for(const o of ORGS){if(!passesOrg(o))continue;const p=project(o.lng,o.lat);const intensity=(o.models.length/8+.75)*(o.tier==='frontier'?1.35:1);const r=(34+o.models.length*9)*camera.zoom*intensity;const col=o.type==='Open'?COLORS.Open:o.type==='Mixed'?COLORS.Multimodal:COLORS.General;const rgb=hexToRgb(col);const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,r);g.addColorStop(0,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.36)`);g.addColorStop(.22,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.16)`);g.addColorStop(.70,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.045)`);g.addColorStop(1,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},0)`);ctx.fillStyle=g;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawFlows(t){if(!flowMode||camera.zoom<.82)return;ctx.save();ctx.globalCompositeOperation='lighter';for(let fi=0;fi<flows.length;fi++){if(perfMode&&fi%2)continue;const f=flows[fi];if(!passesOrg(f.a)||!passesOrg(f.b))continue;const a=project(f.a.lng,f.a.lat),b=project(f.b.lng,f.b.lat);const mx=(a.x+b.x)/2,my=(a.y+b.y)/2-Math.min(180,Math.hypot(a.x-b.x,a.y-b.y)*.24);const rgb=hexToRgb(f.color);ctx.strokeStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${camera.zoom>1.7?0.045:0.075})`;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.quadraticCurveTo(mx,my,b.x,b.y);ctx.stroke();const u=(t*.00011+f.phase)%1;const q=quad(a,{x:mx,y:my},b,u);const q2=quad(a,{x:mx,y:my},b,Math.min(1,u+.012));ctx.strokeStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.85)`;ctx.lineWidth=1.8;ctx.beginPath();ctx.moveTo(q.x,q.y);ctx.lineTo(q2.x,q2.y);ctx.stroke();ctx.fillStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.80)`;ctx.beginPath();ctx.arc(q.x,q.y,2.2,0,Math.PI*2);ctx.fill()}ctx.restore()}
function quad(a,c,b,t){const x=(1-t)*(1-t)*a.x+2*(1-t)*t*c.x+t*t*b.x;const y=(1-t)*(1-t)*a.y+2*(1-t)*t*c.y+t*t*b.y;return {x,y}}
function drawClouds(t){if(!densityMode)return;ctx.save();ctx.globalCompositeOperation='lighter';const z=camera.zoom;for(let ci=0;ci<clouds.length;ci++){if(perfMode&&ci%2)continue;const p0=clouds[ci];const o=ORGS[p0.oi];if(!passesOrg(o))continue;const cat=p0.cat;if(active!=='All'&&active!=='Open'&&cat!==active&&!(active==='Open'&&(cat==='Open'||o.type==='Open')))continue;const op=project(o.lng,o.lat);const a=p0.angle+Math.sin(t*.00045+p0.phase)*.08+p0.spin*t;const scale=z*(z<1?0.86:1);const x=op.x+Math.cos(a)*p0.radius*scale;const y=op.y+Math.sin(a)*p0.radius*.67*scale+(seeded(p0.oi*99+p0.mi)*6-3)*scale; if(x<-80||x>W+80||y<-80||y>H+80)continue;const col=categoryColor(cat,o.type);const rgb=hexToRgb(col);let alpha=p0.alpha*(z<1.1?.74:.62); if(selected){if(selected.kind==='org'&&selected.data.id!==o.id)alpha*=.26; if(selected.kind==='country'&&selected.data.country!==o.country)alpha*=.30}ctx.fillStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`;ctx.strokeStyle=ctx.fillStyle;const size=p0.size*(z<1?1:Math.min(2.5,z*.95)); if(p0.shape==='tri'){ctx.beginPath();ctx.moveTo(x,y-size*1.7);ctx.lineTo(x+size*1.55,y+size*1.3);ctx.lineTo(x-size*1.55,y+size*1.3);ctx.closePath();ctx.fill()}else if(p0.shape==='dash'){ctx.lineWidth=Math.max(.8,size*.65);ctx.beginPath();ctx.moveTo(x-size*2,y);ctx.lineTo(x+size*2,y+size*.7);ctx.stroke()}else{ctx.beginPath();ctx.arc(x,y,size,0,Math.PI*2);ctx.fill()}}ctx.restore()}
function drawMiniTiles(t){const z=camera.zoom;if(z<1.22)return;ctx.save();ctx.globalCompositeOperation='source-over';const maxTiles=perfMode?(z>2.2?24:10):(z>2.2?46:22);let count=0;for(const o of topOrgs){if(!passesOrg(o)||count>=maxTiles)continue;if(selected&&selected.kind==='country'&&selected.data.country!==o.country&&z<2.4)continue;const op=project(o.lng,o.lat);const seed=hash(o.name);const x=op.x+(seeded(seed+1)-.5)*110*z;const y=op.y-34*z+(seeded(seed+2)-.5)*72*z;if(x<-100||x>W+100||y<-100||y>H+100)continue;const model=o.models[0]||o.name;const cat=o.cats[0]||'General';const col=categoryColor(cat,o.type);drawTile(model,o.name,x,y,col,z);count++}ctx.restore()}
function drawTile(model,org,x,y,color,z){const w=Math.min(98,54+model.length*4.5)*Math.min(1.15,z*.55),h=42*Math.min(1.15,z*.55);const rgb=hexToRgb(color);ctx.save();ctx.shadowColor=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.55)`;ctx.shadowBlur=16;roundRect(x-w/2,y-h/2,w,h,9);ctx.fillStyle=`rgba(12,14,28,.78)`;ctx.fill();ctx.strokeStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.55)`;ctx.lineWidth=1;ctx.stroke();ctx.shadowBlur=0;ctx.fillStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.18)`;roundRect(x-w/2+4,y-h/2+4,18,18,6);ctx.fill();ctx.fillStyle='#fff';ctx.font=`900 ${Math.max(9,h*.30)}px Inter,Arial`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(model[0]||'M',x-w/2+13,y-h/2+13);ctx.textAlign='left';ctx.font=`850 ${Math.max(9,h*.25)}px Inter,Arial`;ctx.fillText(model.slice(0,13),x-w/2+27,y-h/2+15);ctx.fillStyle='rgba(210,218,240,.72)';ctx.font=`700 ${Math.max(7,h*.18)}px Inter,Arial`;ctx.fillText(org.slice(0,15),x-w/2+27,y-h/2+28);ctx.restore()}

function computePaperGroups(){const groups=new Map();for(const m of allModels){const meta=getModelMeta(m);if(meta.paperId){if(!groups.has(meta.paperId))groups.set(meta.paperId,[]);groups.get(meta.paperId).push(m)}}return groups}
function getOrgById(id){return ORGS.find(o=>o.id===id)}
function getOrgMeta(o){return ORG_META[o.name]||{}}
function getModelMeta(m){return MODEL_META[m.name]||MODEL_META[`${m.org}::${m.name}`]||{}}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function linkBtn(label,url){return url?`<a class="link-btn" target="_blank" rel="noopener" href="${esc(url)}" onclick="event.stopPropagation()">${label}</a>`:''}
function miniLink(label,url){return url?`<a target="_blank" rel="noopener" href="${esc(url)}" onclick="event.stopPropagation()">${label}</a>`:''}
function modelCardLinks(meta){const links=[miniLink('Paper',meta.paperUrl),miniLink('HF',meta.hf),miniLink('Web',meta.modelUrl)].filter(Boolean).join('');return links?`<div class="mini-links">${links}</div>`:''}
function modelObject(o,i){return {name:o.models[i],org:o.name,country:o.country,city:o.city,lat:o.lat,lng:o.lng,type:o.type,cat:o.cats[i%o.cats.length]||'General',hot:o.hot,tier:o.tier,index:i,orgId:o.id}}
function getRelatedModelsByPaper(m){const meta=getModelMeta(m);if(!meta.paperId)return[];return (paperGroups.get(meta.paperId)||[]).filter(x=>!(x.orgId===m.orgId&&x.index===m.index))}
function completenessForOrg(o){const meta=getOrgMeta(o);let paper=0,hf=0,web=0;for(let i=0;i<o.models.length;i++){const md=getModelMeta(modelObject(o,i));if(md.paperUrl)paper++;if(md.hf)hf++;if(md.modelUrl)web++}return {website:!!meta.website,founders:(meta.founders||[]).length,paper,hf,web,total:o.models.length}}
function applyTheme(id){const theme=THEMES[id]||THEMES.nebula;currentTheme=THEMES[id]?id:'nebula';COLORS={...theme.palette};const root=document.documentElement;Object.entries(theme.vars||{}).forEach(([k,v])=>root.style.setProperty(k,v));root.dataset.theme=currentTheme;localStorage.setItem('worldroadmap-theme',currentTheme)}
function renderThemeSelect(){const el=document.getElementById('themeSelect');if(!el)return;el.innerHTML=Object.entries(THEMES).map(([id,t])=>`<option value="${id}">${t.name}</option>`).join('');el.value=currentTheme;el.onchange=()=>{applyTheme(el.value);renderFilters();toast('主题：'+THEMES[currentTheme].name)}}

function coverageStats(){const metaModels=allModels.map(m=>getModelMeta(m));return {papers:metaModels.filter(m=>m.paperUrl).length,hf:metaModels.filter(m=>m.hf).length,modelPages:metaModels.filter(m=>m.modelUrl).length,orgWeb:Object.values(ORG_META).filter(o=>o.website).length,paperGroups:[...paperGroups.values()].filter(g=>g.length>1).length}}
function renderDefaultDetail(){const c=coverageStats();document.getElementById('detail').innerHTML=`<h3>Selected / 当前选择</h3><h2>全球模型视角</h2><div class="badges"><span class="badge">拖拽平移</span><span class="badge">滚轮缩放</span><span class="badge">点击自动放大</span><span class="badge">H/F/D/L/P 快捷键</span></div><p class="muted">v5 细节打磨版：更多主题色、标签/性能开关、选中模型真实点位高亮；搜索可直接命中模型；论文/HF 缺失时不会显示空链接。</p><div class="card data-card"><b>链接覆盖率 / Link Coverage</b><div class="coverage-grid"><span><strong>${c.papers}</strong><small>Paper/Card</small></span><span><strong>${c.hf}</strong><small>Hugging Face</small></span><span><strong>${c.orgWeb}</strong><small>Company Web</small></span><span><strong>${c.paperGroups}</strong><small>Paper Groups</small></span></div><p class="source-note">后续只要在 src/data.js 的 MODEL_META / ORG_META 补充链接，详情卡和关系线会自动更新。</p></div><div class="card"><b>快捷键</b><p class="muted"><kbd>H</kbd> 全球视角　<kbd>F</kbd> 流光　<kbd>D</kbd> 密度　<kbd>L</kbd> 标签　<kbd>P</kbd> 性能　<kbd>/</kbd> 搜索</p></div>`}
function findModelMatch(q){q=(q||'').toLowerCase();for(const o of ORGS){for(let i=0;i<o.models.length;i++){const m=modelObject(o,i);const blob=(m.name+' '+m.org+' '+m.country+' '+m.city+' '+m.cat).toLowerCase();if(blob.includes(q))return {o,m}}}return null}
function orgResearchSummary(o){const rows=o.models.map((name,i)=>{const md=getModelMeta(modelObject(o,i));return {paper:!!md.paperUrl,hf:!!md.hf,web:!!md.modelUrl}});return `<div class="kpi-grid"><div class="kpi"><b>${rows.filter(r=>r.paper).length}</b><span>Paper/Card</span></div><div class="kpi"><b>${rows.filter(r=>r.hf).length}</b><span>Hugging Face</span></div><div class="kpi"><b>${rows.filter(r=>r.web).length}</b><span>Official Page</span></div></div>`}
function detailTrail(parts){return `<div class="breadcrumb">${parts.filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('')}</div>`}

function fallbackAvatar(name){const initials=String(name).split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();return `data:image/svg+xml;utf8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" width="160" height="160"><defs><linearGradient id="g" x1="0" x2="1"><stop stop-color="#243052"/><stop offset="1" stop-color="#0b1020"/></linearGradient></defs><rect width="160" height="160" rx="28" fill="url(#g)"/><text x="80" y="92" text-anchor="middle" font-size="44" fill="white" font-family="Arial" font-weight="900">${initials}</text></svg>` )}`}
function founderImgTag(f){const img=f.image||fallbackAvatar(f.name);return `<img src="${esc(img)}" alt="${esc(f.name)}" loading="lazy" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src='${fallbackAvatar(f.name)}'"/>`}
function openFounderModal(name,img,bio,url){const modal=document.getElementById('personModal');document.getElementById('modalName').textContent=name;document.getElementById('modalBio').textContent=bio||'';const im=document.getElementById('modalImg');im.src=img||fallbackAvatar(name);im.onerror=()=>{im.onerror=null;im.src=fallbackAvatar(name)};const a=document.getElementById('modalLink');a.href=url||'#';a.style.display=url?'inline-flex':'none';modal.classList.add('show');modal.setAttribute('aria-hidden','false')}
function closeFounderModal(){const modal=document.getElementById('personModal');modal.classList.remove('show');modal.setAttribute('aria-hidden','true')}
function drawPaperLinks(t){if(!selected||selected.kind!=='model')return;const m=selected.data;const meta=getModelMeta(m);if(!meta.paperId)return;const related=getRelatedModelsByPaper(m);if(!related.length)return;const srcOrg=getOrgById(m.orgId);if(!srcOrg)return;const a=modelPosition(srcOrg,m.index,srcOrg.models.length,t);ctx.save();ctx.globalCompositeOperation='lighter';for(const r of related){const dstOrg=getOrgById(r.orgId);if(!dstOrg||!passesOrg(dstOrg))continue;const b=modelPosition(dstOrg,r.index,dstOrg.models.length,t);const c={x:(a.x+b.x)/2,y:(a.y+b.y)/2-34*camera.zoom};const col=categoryColor(m.cat,m.type);const rgb=hexToRgb(col);ctx.lineWidth=1.6;ctx.strokeStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.56)`;ctx.setLineDash([7,7]);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.quadraticCurveTo(c.x,c.y,b.x,b.y);ctx.stroke();ctx.setLineDash([]);const u=(t*.00018)%1;const p=quad(a,c,b,u);drawGlow(p.x,p.y,16*camera.zoom,col,.28);ctx.fillStyle=col;ctx.beginPath();ctx.arc(p.x,p.y,2.5*camera.zoom,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawOrgPaperLinks(t){if(!selected||selected.kind!=='org'||camera.zoom<1.55)return;const o=selected.data;if(!passesOrg(o))return;const groups=new Map();for(let i=0;i<o.models.length;i++){const mm=modelObject(o,i);const meta=getModelMeta(mm);if(!meta.paperId)continue;if(!groups.has(meta.paperId))groups.set(meta.paperId,[]);groups.get(meta.paperId).push(i)}ctx.save();ctx.globalCompositeOperation='lighter';for(const idxs of groups.values()){if(idxs.length<2)continue;for(let j=0;j<idxs.length-1;j++){const a=modelPosition(o,idxs[j],o.models.length,t);const b=modelPosition(o,idxs[j+1],o.models.length,t);const mid={x:(a.x+b.x)/2,y:(a.y+b.y)/2-18*camera.zoom};const mm=modelObject(o,idxs[j]);const col=categoryColor(mm.cat,mm.type);const rgb=hexToRgb(col);ctx.setLineDash([5,6]);ctx.lineWidth=1.2;ctx.strokeStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.42)`;ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.quadraticCurveTo(mid.x,mid.y,b.x,b.y);ctx.stroke();ctx.setLineDash([])}}ctx.restore()}
function focusModelFromDetail(orgId,index){const o=getOrgById(orgId);if(!o)return;const m=modelObject(o,index);selected={kind:'model',data:m};flyTo(m.lng,m.lat,3.2);renderDetailModel(m,o);toast('模型节点：'+m.name)}
window.focusModelFromDetail=focusModelFromDetail;window.openFounderModal=openFounderModal;window.closeFounderModal=closeFounderModal;

function hexToRgb(hex){hex=hex.replace('#','');return [parseInt(hex.slice(0,2),16),parseInt(hex.slice(2,4),16),parseInt(hex.slice(4,6),16)]}
function categoryColor(cat,type){return cat==='Open'||type==='Open'?COLORS.Open:(COLORS[cat]||COLORS.General)}
function passesOrg(o){if(query){const blob=(o.name+' '+o.country+' '+o.city+' '+o.models.join(' ')).toLowerCase();if(!blob.includes(query))return false}if(active==='All')return true;if(active==='Open')return o.type==='Open'||o.cats.includes('Open');return o.cats.includes(active)}
function passesModel(m,o){if(query){const blob=(m.name+' '+m.org+' '+m.country+' '+m.city).toLowerCase();if(!blob.includes(query)&&!(o.name+' '+o.country+' '+o.city).toLowerCase().includes(query))return false}if(active==='All')return true;if(active==='Open')return m.type==='Open'||m.cat==='Open'||o.type==='Open';return m.cat===active}
function modelPosition(o,i,total,t){const op=project(o.lng,o.lat);const seed=(hash(o.name)+i*41)%360;const angle=(seed/180)*Math.PI+Math.sin(t*.00042+i*.77)*.055;const spread=(24+Math.sqrt(total)*11+(i%5)*5)*camera.zoom;const ring=spread*(1+Math.floor(i/8)*.42);return {x:op.x+Math.cos(angle)*ring,y:op.y+Math.sin(angle)*ring*.69,base:op}}
function drawGlow(x,y,r,color,alpha=.2){const rgb=hexToRgb(color);ctx.save();ctx.globalCompositeOperation='lighter';const g=ctx.createRadialGradient(x,y,0,x,y,r);g.addColorStop(0,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`);g.addColorStop(.35,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha*.35})`);g.addColorStop(1,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},0)`);ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.restore()}
function drawNodeLabel(text,x,y,size=12,alpha=1){if(!labelsMode)return;ctx.save();ctx.globalAlpha=alpha;ctx.font=`850 ${size}px Inter,Arial`;ctx.textAlign='center';ctx.textBaseline='bottom';ctx.shadowColor='rgba(0,0,0,.95)';ctx.shadowBlur=10;ctx.fillStyle='rgba(245,248,255,.95)';ctx.fillText(text,x,y);ctx.restore()}
function drawRoundedLabel(text,x,y,color){if(!labelsMode)return;ctx.save();ctx.font='850 11px Inter,Arial';const w=ctx.measureText(text).width+18;const h=22;roundRect(x-w/2,y-h,w,h,8);const rgb=hexToRgb(color);ctx.fillStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.15)`;ctx.strokeStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.48)`;ctx.lineWidth=1;ctx.fill();ctx.stroke();ctx.fillStyle='rgba(255,255,255,.94)';ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(text,x,y-h/2);ctx.restore()}
function drawNodes(t){hover=null;let best=Infinity;const z=camera.zoom;ctx.save();ctx.globalCompositeOperation='source-over';for(const o of ORGS){if(!passesOrg(o))continue;const op=project(o.lng,o.lat);if(op.x<-150||op.x>W+150||op.y<-150||op.y>H+150)continue;const baseColor=o.type==='Open'?COLORS.Open:o.type==='Mixed'?COLORS.Multimodal:COLORS.General;const orgR=(5.8+Math.min(12,o.models.length)*.82)*(o.tier==='frontier'?1.26:1)*z; if(z>1.02){ctx.lineWidth=.62;for(let i=0;i<o.models.length;i++){const m={name:o.models[i],org:o.name,country:o.country,city:o.city,lat:o.lat,lng:o.lng,type:o.type,cat:o.cats[i%o.cats.length]||'General',hot:o.hot,tier:o.tier,index:i,orgId:o.id};if(!passesModel(m,o))continue;const mp=modelPosition(o,i,o.models.length,t);const col=categoryColor(m.cat,m.type);ctx.strokeStyle='rgba(196,222,255,.10)';ctx.beginPath();ctx.moveTo(op.x,op.y);ctx.lineTo(mp.x,mp.y);ctx.stroke();const mr=(2.7+(i===0?1.5:0))*z*(o.tier==='frontier'?1.17:1);drawGlow(mp.x,mp.y,mr*6.5,col,.18);ctx.fillStyle=col;ctx.shadowColor=col;ctx.shadowBlur=12;ctx.beginPath();ctx.arc(mp.x,mp.y,mr,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;if(z>2.05||(selected&&selected.kind==='org'&&selected.data.id===o.id)){if(i<14)drawRoundedLabel(m.name,mp.x,mp.y-11*z,col)}const d=distance(pointer.x,pointer.y,mp.x,mp.y);if(d<Math.max(16,mr*4)&&d<best){best=d;hover={kind:'model',data:m,org:o,x:mp.x,y:mp.y}}}}
 drawGlow(op.x,op.y,orgR*7.2,baseColor,o.tier==='frontier'?.32:.20);ctx.fillStyle=baseColor;ctx.shadowColor=baseColor;ctx.shadowBlur=26;ctx.beginPath();ctx.arc(op.x,op.y,orgR,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='rgba(255,255,255,.88)';ctx.lineWidth=1.25;ctx.stroke();ctx.fillStyle='rgba(5,8,16,.78)';ctx.beginPath();ctx.arc(op.x,op.y,Math.max(6,orgR*.56),0,Math.PI*2);ctx.fill();ctx.fillStyle='#fff';ctx.font=`900 ${Math.max(8,orgR*.70)}px Inter,Arial`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.fillText(o.name[0],op.x,op.y+.5);const d=distance(pointer.x,pointer.y,op.x,op.y);if(d<Math.max(18,orgR*2.8)&&d<best){best=d;hover={kind:'org',data:o,org:o,x:op.x,y:op.y}}if(z>1.14||o.tier==='frontier'||o.models.length>=5)drawNodeLabel(o.name,op.x,op.y-orgR-7,z>1.7?12:11,z>1.15?1:.82)}ctx.restore()}
function drawSelection(){if(!selected)return;let p,label;if(selected.kind==='country'){const f=countryFeatureMap.get(selected.data.country);if(!f)return;p=project(f.center[0],f.center[1]);label=selected.data.country}else if(selected.kind==='org'){p=project(selected.data.lng,selected.data.lat);label=selected.data.name}else{const o=getOrgById(selected.data.orgId)||ORGS.find(x=>x.name===selected.data.org);p=o?modelPosition(o,selected.data.index,o.models.length,performance.now()):project(selected.data.lng,selected.data.lat);label=selected.data.name}ctx.save();ctx.strokeStyle='rgba(255,218,160,.92)';ctx.lineWidth=1.5;ctx.globalCompositeOperation='lighter';for(let i=0;i<3;i++){ctx.globalAlpha=.72-i*.18;ctx.beginPath();ctx.arc(p.x,p.y,(30+i*18)*camera.zoom,0,Math.PI*2);ctx.stroke()}ctx.restore();drawNodeLabel(label,p.x,p.y-38*camera.zoom,14,1)}
function drawTooltip(){if(hover){tooltip.style.display='block';tooltip.style.left=Math.min(W-310,hover.x+16)+'px';tooltip.style.top=Math.min(H-160,hover.y+16)+'px';const d=hover.data;if(hover.kind==='org')tooltip.innerHTML=`<b>${d.name}</b><span>${d.city}, ${countryLabel(d.country)}<br>${d.models.length} 模型 / 模型族 · ${d.type}<br>点击自动放大到公司模型星云</span>`;else{const md=getModelMeta(d);const tags=[md.paperUrl?'Paper':'',md.hf?'HF':'',md.modelUrl?'Official':''].filter(Boolean).join(' · ');tooltip.innerHTML=`<b>${d.name}</b><span>${d.org}<br>${d.cat} · ${d.type}${tags?'<br>'+tags:''}<br>点击查看模型详情</span>`}}else if(hoverCountry){const dc=dataCountryName(hoverCountry.name);const s=countryStats.find(c=>c.country===dc);tooltip.style.display='block';const p=project(hoverCountry.center[0],hoverCountry.center[1]);tooltip.style.left=Math.min(W-290,p.x+16)+'px';tooltip.style.top=Math.min(H-140,p.y+16)+'px';tooltip.innerHTML=`<b>${countryLabel(dc)}</b><span>${s?`${s.orgs} 公司 / 实验室 · ${s.models} 模型`:'暂无内置机构数据'}<br>点击进入国家视角</span>`}else tooltip.style.display='none'}
function render(t=0){if(lastT){const dt=t-lastT;fps=fps*.92+(1000/Math.max(16,dt))*.08}lastT=t;if(t-lastFpsUpdate>520){const f=document.getElementById('fpsMeter');if(f)f.textContent=Math.round(fps)+' FPS · '+(perfMode?'省电':'高画质');lastFpsUpdate=t}smooth();drawBackground(t);drawGraticule();drawCountries();drawDensity(t);drawFlows(t);drawPaperLinks(t);drawOrgPaperLinks(t);drawClouds(t);drawMiniTiles(t);drawNodes(t);drawSelection();drawTooltip();requestAnimationFrame(render)}
function roundRect(x,y,w,h,r){ctx.beginPath();ctx.moveTo(x+r,y);ctx.arcTo(x+w,y,x+w,y+h,r);ctx.arcTo(x+w,y+h,x,y+h,r);ctx.arcTo(x,y+h,x,y,r);ctx.arcTo(x,y,x+w,y,r);ctx.closePath()}
function distance(a,b,c,d){return Math.hypot(a-c,b-d)}
function pointInRing(pt,ring){let x=pt.lng,y=pt.lat,inside=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const xi=ring[i][0],yi=ring[i][1],xj=ring[j][0],yj=ring[j][1];const intersect=((yi>y)!==(yj>y))&&(x<(xj-xi)*(y-yi)/(yj-yi+1e-9)+xi);if(intersect)inside=!inside}return inside}
function findCountryAt(x,y){const ll=inverse(x,y);for(const f of WORLD.features){const b=f.bbox;if(ll.lng<b[0]||ll.lng>b[2]||ll.lat<b[1]||ll.lat>b[3])continue;for(const ring of f.polygons){if(pointInRing(ll,ring))return f}}return null}
canvas.addEventListener('pointermove',e=>{pointer.x=e.clientX;pointer.y=e.clientY;if(pointer.down){const dx=e.clientX-pointer.lastX,dy=e.clientY-pointer.lastY;if(Math.abs(dx)+Math.abs(dy)>2)pointer.moved=true;camera.targetX+=dx;camera.targetY+=dy;clampCamera();pointer.lastX=e.clientX;pointer.lastY=e.clientY}else{hoverCountry=hover?null:findCountryAt(pointer.x,pointer.y)}});
canvas.addEventListener('pointerdown',e=>{pointer.down=true;pointer.moved=false;pointer.lastX=e.clientX;pointer.lastY=e.clientY;canvas.setPointerCapture(e.pointerId)});
canvas.addEventListener('pointerup',e=>{pointer.down=false;if(pointer.moved)return;if(hover){if(hover.kind==='org'){selected={kind:'org',data:hover.data};flyTo(hover.data.lng,hover.data.lat,2.88);renderDetailOrg(hover.data);toast('公司锚点：'+hover.data.name)}else{selected={kind:'model',data:hover.data};flyTo(hover.data.lng,hover.data.lat,3.15);renderDetailModel(hover.data,hover.org);toast('模型节点：'+hover.data.name)}}else{const c=findCountryAt(e.clientX,e.clientY);if(c){const dc=dataCountryName(c.name);const s=countryStats.find(x=>x.country===dc)||{country:dc,models:0,orgs:0,open:0};selected={kind:'country',data:s};flyTo(c.center[0],c.center[1],dc==='United States'||dc==='China'?1.95:2.6);renderDetailCountry(s);renderCountryList();toast('国家视角：'+countryLabel(dc))}}});
canvas.addEventListener('wheel',e=>{e.preventDefault();const old=camera.targetZoom;const next=Math.max(.70,Math.min(5.8,old*(e.deltaY<0?1.13:.89)));const k=next/old;camera.targetX=pointer.x-W/2+(camera.targetX-(pointer.x-W/2))*k;camera.targetY=pointer.y-H/2+(camera.targetY-(pointer.y-H/2))*k;camera.targetZoom=next;clampCamera()},{passive:false});
function computeCountryStats(){const map=new Map();for(const o of ORGS){if(!map.has(o.country))map.set(o.country,{country:o.country,orgs:0,models:0,open:0});const s=map.get(o.country);s.orgs++;s.models+=o.models.length;if(o.type==='Open')s.open+=o.models.length}return [...map.values()].sort((a,b)=>b.models-a.models)}
function countryLabel(c){return CJK_COUNTRY[c]?`${c} · ${CJK_COUNTRY[c]}`:c}
function renderStats(){document.getElementById('sModels').textContent=allModels.length;document.getElementById('sOrgs').textContent=ORGS.length;document.getElementById('sCountries').textContent=countryStats.length;const open=allModels.filter(m=>m.type==='Open'||m.cat==='Open').length;document.getElementById('sOpen').textContent=Math.round(open/allModels.length*100)+'%';const sp=document.getElementById('sPapers');if(sp)sp.textContent=[...paperGroups.values()].filter(g=>g.length).length}
function renderCountryList(){const el=document.getElementById('countryList');el.innerHTML='';const q=query.toLowerCase();countryStats.filter(s=>!q||countryLabel(s.country).toLowerCase().includes(q)||ORGS.some(o=>o.country===s.country&&(o.name+' '+o.city+' '+o.models.join(' ')).toLowerCase().includes(q))).forEach(s=>{const row=document.createElement('div');row.className='country '+(selected&&selected.kind==='country'&&selected.data.country===s.country?'active':'');row.innerHTML=`<div><b>${countryLabel(s.country)}</b><small>${s.orgs} companies · ${s.models} models</small><div class="bar"><i style="width:${Math.max(5,s.models/maxCountry*100)}%"></i></div></div><strong>${s.models}</strong>`;row.onclick=()=>{const f=countryFeatureMap.get(s.country);const list=ORGS.filter(o=>o.country===s.country);const center=f?f.center:[list.reduce((a,o)=>a+o.lng,0)/list.length,list.reduce((a,o)=>a+o.lat,0)/list.length];selected={kind:'country',data:s};flyTo(center[0],center[1],s.country==='United States'||s.country==='China'?1.95:2.6);renderDetailCountry(s);renderCountryList()};el.appendChild(row)})}
function renderFilters(){const box=document.getElementById('chips');box.innerHTML='';for(const f of FILTERS){const b=document.createElement('button');b.className='chip '+(active===f?'active':'');b.textContent=f;b.onclick=()=>{active=f;renderFilters();toast('筛选：'+f)};box.appendChild(b)}document.getElementById('legend').innerHTML=Object.entries(COLORS).filter(([k])=>FILTERS.includes(k)||['Safety','Benchmark','3D'].includes(k)).map(([k,v])=>`<span><i style="background:${v};color:${v}"></i>${k}</span>`).join('')}
function renderDetailCountry(s){const list=ORGS.filter(o=>o.country===s.country).sort((a,b)=>b.models.length-a.models.length);document.getElementById('detail').innerHTML=`<h3>Country View / 国家视角</h3>${detailTrail(['World',countryLabel(s.country)])}<h2>${countryLabel(s.country)}</h2><div class="badges"><span class="badge">${s.orgs} companies</span><span class="badge">${s.models} models</span><span class="badge">${s.open} open-family</span></div><p class="muted">点击公司锚点可进一步放大到机构模型星云；有官网、创始人、论文或 Hugging Face 的条目会在详情里显示可点击链接。</p>${list.map(o=>{const meta=getOrgMeta(o);return `<div class="card" onclick="selected={kind:'org',data:ORGS.find(x=>x.id==='${o.id}')};flyTo(${o.lng},${o.lat},2.88);renderDetailOrg(ORGS.find(x=>x.id==='${o.id}'))"><b>${esc(o.name)}</b><p>${esc(o.city)} · ${esc(o.type)} · ${o.models.length} models</p><div class="link-row">${linkBtn('Website',meta.website)}</div></div>`}).join('')}`}function renderDetailOrg(o){const meta=getOrgMeta(o);const founderHtml=(meta.founders||[]).map(f=>`<div class="founder" onclick="openFounderModal('${esc(f.name)}','${esc(f.image||'')}','${esc((f.role||'')+' · '+o.name)}','${esc(f.url||meta.website||'')}')">${founderImgTag(f)}<div><b>${esc(f.name)}</b><small>${esc(f.role||'Founder')}</small></div></div>`).join('')||`<p class="empty-note">暂未加入创始人图片数据，后续可在 ORG_META 中补充。</p>`;document.getElementById('detail').innerHTML=`<h3>Company Anchor / 公司锚点</h3>${detailTrail(['World',countryLabel(o.country),o.name])}<h2>${esc(o.name)}</h2><p class="muted">${esc(o.city)}, ${countryLabel(o.country)}</p><div class="badges"><span class="badge">${esc(o.type)}</span><span class="badge">${esc(o.tier)}</span><span class="badge">${o.models.length} models</span>${[...new Set(o.cats)].slice(0,6).map(c=>`<span class="badge">${esc(c)}</span>`).join('')}</div>${orgResearchSummary(o)}<div class="link-row">${linkBtn('Company Website',meta.website)}${linkBtn('HF Org',meta.hf)}${linkBtn('GitHub',meta.github)}</div>${(()=>{const h=completenessForOrg(o);return `<div class="data-health"><div class="health-pill"><b>${h.paper}/${h.total}</b><span>Paper linked</span></div><div class="health-pill"><b>${h.hf}/${h.total}</b><span>HF linked</span></div><div class="health-pill"><b>${h.founders}</b><span>founder cards</span></div></div>`})()}<div class="card"><b>地图绑定</b><p>公司/实验室锚点：${o.lat.toFixed(3)}, ${o.lng.toFixed(3)}。彩色粒子代表模型/模型族；同论文模型会在选中后用发光虚线连起来。</p></div><div class="card"><b>Founders / 创始人或核心团队</b><div class="founders">${founderHtml}</div><div class="source-note">图片优先使用公开可访问来源；没有可靠图片时显示首字母头像，占位不会影响链接。</div></div><div class="models-grid">${o.models.map((m,i)=>{const c=o.cats[i%o.cats.length]||'General';const mm=modelObject(o,i);const md=getModelMeta(mm);return `<div class="model-chip" onclick="focusModelFromDetail('${o.id}',${i})"><i style="background:${categoryColor(c,o.type)};color:${categoryColor(c,o.type)}"></i>${esc(m)}<br><span class="muted">${esc(c)}${md.paperId?' · paper-linked':''}</span>${modelCardLinks(md)}</div>`}).join('')}</div>`}function renderDetailModel(m,o){const meta=getModelMeta(m);const orgMeta=getOrgMeta(o);const related=getRelatedModelsByPaper(m);const paperLinks=[linkBtn('Paper / System Card',meta.paperUrl),linkBtn('Hugging Face',meta.hf),linkBtn('Official Model Page',meta.modelUrl),linkBtn('Company Website',orgMeta.website)].filter(Boolean).join('');document.getElementById('detail').innerHTML=`<h3>Model Node / 模型节点</h3>${detailTrail(['World',countryLabel(m.country),m.org,m.name])}<h2>${esc(m.name)}</h2><p class="muted">${esc(m.org)} · ${esc(m.city)}, ${countryLabel(m.country)}</p><div class="badges"><span class="badge">${esc(m.cat)}</span><span class="badge">${esc(m.type)}</span><span class="badge">${esc(m.tier)}</span><span class="badge">Lat ${m.lat.toFixed(2)}</span><span class="badge">Lng ${m.lng.toFixed(2)}</span></div>${paperLinks?`<div class="card paper-box"><b class="paper-title">${esc(meta.paperTitle||'模型链接')}</b><div class="link-row">${paperLinks}</div><p class="muted">如果某模型没有论文或 Hugging Face 条目，这里会自动不显示对应按钮。</p></div>`:`<div class="card"><b>暂无论文/HF 链接</b><p class="muted">该模型目前没有在内置数据中绑定论文或 Hugging Face 页面；可以在 MODEL_META 里继续补充。</p></div>`}<div class="card"><b>同论文关系线</b>${related.length?`<p class="muted">这些模型共享同一个 paperId。选中当前模型时，地图上会显示发光虚线连接。</p><div class="related-list">${related.map(r=>`<span class="related-pill" onclick="focusModelFromDetail('${r.orgId}',${r.index})">${esc(r.name)} · ${esc(r.org)}</span>`).join('')}</div>`:`<p class="muted">没有其他模型绑定到同一篇论文。</p>`}</div><div class="card"><b>同机构模型</b><p>${o.models.map(esc).join(' · ')}</p></div>`}function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),1400)}
