function domainFromUrl(url){try{return url?new URL(url).hostname.replace(/^www\./,''):''}catch(_){return''}}
function websiteFromDomain(domain){return domain?`https://${domain}`:''}
function logoUrlForDomain(domain){return domain?`https://www.google.com/s2/favicons?domain=${encodeURIComponent(domain)}&sz=128`:''}
function jsArg(s){return JSON.stringify(String(s??'')).replace(/</g,'\\u003c')}
function typeLabel(type){return type==='Open'?'开放模型生态':type==='Mixed'?'开放与商业并行':'商业闭源生态'}
function tierLabel(tier){return ({frontier:'前沿模型机构',major:'重要产业机构',creative:'生成式创意机构',lab:'研究实验室',startup:'创业团队',platform:'模型平台',public:'公共项目',enterprise:'企业智能平台',agent:'Agent 公司',code:'代码智能机构',audio:'语音音频机构',voice:'语音 Agent 机构',infra:'模型基础设施',language:'语言智能机构',app:'AI 应用公司'}[tier]||tier)}
function categoryLabel(cat){return ({General:'通用语言',Reasoning:'推理能力',Code:'代码生成',Multimodal:'多模态理解',Image:'图像生成',Video:'视频生成',Audio:'语音音频',Open:'开源模型',Agent:'智能体',Embedding:'向量检索',Science:'科学计算',Benchmark:'评测基准',Safety:'安全治理','3D':'三维生成'}[cat]||cat)}
function getDisplayOrgMeta(o){const raw=getOrgMeta(o);const domain=raw.domain||ORG_BRAND_DOMAINS[o.name]||domainFromUrl(raw.website);const website=raw.website||websiteFromDomain(domain);const founders=(raw.founders&&raw.founders.length?raw.founders:ORG_PEOPLE_HINTS[o.name]||[{name:o.name,role:tierLabel(o.tier)}]);return {...raw,domain,website,logo:raw.logo||logoUrlForDomain(domain),founders,about:raw.about||companyAbout(o)}}
function coverageStats(){const metaModels=allModels.map(m=>getModelMeta(m));return {papers:metaModels.filter(m=>m.paperUrl).length,hf:metaModels.filter(m=>m.hf).length,modelPages:metaModels.filter(m=>m.modelUrl).length,orgWeb:ORGS.filter(o=>getDisplayOrgMeta(o).website).length,paperGroups:[...paperGroups.values()].filter(g=>g.length>1).length}}
function orgLogoTag(o,meta=getDisplayOrgMeta(o)){const fallback=fallbackAvatar(o.name);const src=meta.logo||fallback;return `<img class="org-logo" src="${esc(src)}" alt="${esc(o.name)} logo" loading="lazy" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src='${esc(fallback)}'"/>`}
function companyAbout(o){const cats=[...new Set(o.cats)].slice(0,4).map(categoryLabel).join('、');const models=o.models.slice(0,4).join('、');return `${o.name} 位于 ${o.city}，在地图中归为${typeLabel(o.type)}和${tierLabel(o.tier)}。代表模型包括 ${models}${o.models.length>4?' 等':''}，主要覆盖 ${cats}。`}
function modelSummary(m,o,meta=getModelMeta(m)){const purpose={General:'面向通用问答、写作和知识工作流',Reasoning:'强调复杂推理、数学和多步骤问题求解',Code:'服务代码生成、软件工程和开发者工具',Multimodal:'连接文本、图像、视频或语音等多模态输入',Image:'用于图像生成、编辑和视觉创作',Video:'用于视频生成、镜头控制或动态内容生产',Audio:'用于语音识别、合成、翻译或音频理解',Open:'开放权重或开放生态模型，便于研究和二次开发',Agent:'面向工具调用、任务规划和自动化执行',Embedding:'用于语义检索、排序和知识库召回',Science:'面向科学、医疗、气象或工程研究场景',Benchmark:'用于模型评测、榜单或能力基准','3D':'用于三维资产、空间内容或视觉生成'}[m.cat]||'用于该机构的核心 AI 能力建设';const source=meta.paperTitle?`关联资料：${meta.paperTitle}`:(meta.modelUrl?'已关联官方模型页面':'以机构公开模型族信息呈现');return `${m.name} 是 ${o.name} 的${categoryLabel(m.cat)}模型/模型族，${purpose}。${source}。`}
function modelMiniSummary(m,o,meta=getModelMeta(m)){return meta.paperTitle?meta.paperTitle:`${categoryLabel(m.cat)} · ${typeLabel(m.type)}`}
function founderCards(o,meta=getDisplayOrgMeta(o)){return meta.founders.map(f=>{const role=f.role||'核心团队';const bio=f.bio||`${role} · ${o.name}`;const img=f.image||fallbackAvatar(f.name);const url=f.url||meta.website||'';return `<div class="founder" onclick="openFounderModal(${jsArg(f.name)},${jsArg(img)},${jsArg(bio)},${jsArg(url)})">${founderImgTag({...f,image:img})}<div><b>${esc(f.name)}</b><small>${esc(role)}</small></div></div>`}).join('')}
function orgStatGrid(o){const rows=o.models.map((name,i)=>getModelMeta(modelObject(o,i)));return `<div class="data-health"><div class="health-pill"><b>${o.models.length}</b><span>模型族</span></div><div class="health-pill"><b>${rows.filter(r=>r.paperUrl||r.modelUrl).length}</b><span>资料页</span></div><div class="health-pill"><b>${[...new Set(o.cats)].length}</b><span>能力方向</span></div></div>`}
function renderDefaultDetail(){const c=coverageStats();document.getElementById('detail').innerHTML=`<h3>Selected / 当前选择</h3><h2>全球模型视角</h2><div class="badges"><span class="badge">拖拽平移</span><span class="badge">滚轮缩放</span><span class="badge">点击公司或模型</span><span class="badge">默认省电</span></div><p class="muted">地图展示全球主要 AI 公司、实验室和模型族。点击公司可查看品牌 logo、公司画像、创始人或核心团队；点击模型可查看模型定位、资料链接和同源模型关系。</p><div class="card data-card"><b>资料覆盖</b><div class="coverage-grid"><span><strong>${c.papers}</strong><small>Paper / Card</small></span><span><strong>${c.hf}</strong><small>Hugging Face</small></span><span><strong>${c.orgWeb}</strong><small>Company Web</small></span><span><strong>${c.paperGroups}</strong><small>Related Sets</small></span></div></div><div class="card"><b>探索方式</b><p class="muted"><kbd>H</kbd> 全球视角　<kbd>D</kbd> 密度　<kbd>L</kbd> 标签　<kbd>P</kbd> 画质　<kbd>/</kbd> 搜索</p></div>`}
function renderDetailCountry(s){const list=ORGS.filter(o=>o.country===s.country).sort((a,b)=>b.models.length-a.models.length);document.getElementById('detail').innerHTML=`<h3>Country View / 国家视角</h3>${detailTrail(['World',countryLabel(s.country)])}<h2>${countryLabel(s.country)}</h2><div class="badges"><span class="badge">${s.orgs} companies</span><span class="badge">${s.models} models</span><span class="badge">${s.open} open-family</span></div><p class="muted">选择一家机构查看品牌、团队、代表模型和资料入口。</p>${list.map(o=>{const meta=getDisplayOrgMeta(o);return `<div class="card org-row" onclick="selected={kind:'org',data:ORGS.find(x=>x.id==='${o.id}')};flyTo(${o.lng},${o.lat},2.88);renderDetailOrg(ORGS.find(x=>x.id==='${o.id}'))">${orgLogoTag(o,meta)}<div><b>${esc(o.name)}</b><p>${esc(o.city)} · ${typeLabel(o.type)} · ${o.models.length} models</p><div class="link-row">${linkBtn('Website',meta.website)}</div></div></div>`}).join('')}`}
function renderDetailOrg(o){const meta=getDisplayOrgMeta(o);document.getElementById('detail').innerHTML=`<h3>Company Anchor / 公司锚点</h3>${detailTrail(['World',countryLabel(o.country),o.name])}<div class="org-hero">${orgLogoTag(o,meta)}<div><h2>${esc(o.name)}</h2><p class="muted">${esc(o.city)}, ${countryLabel(o.country)}</p></div></div><div class="badges"><span class="badge">${typeLabel(o.type)}</span><span class="badge">${tierLabel(o.tier)}</span><span class="badge">${o.models.length} models</span>${[...new Set(o.cats)].slice(0,5).map(c=>`<span class="badge">${categoryLabel(c)}</span>`).join('')}</div><div class="card"><b>公司画像</b><p>${esc(meta.about)}</p><div class="link-row">${linkBtn('Company Website',meta.website)}${linkBtn('HF Org',meta.hf)}${linkBtn('GitHub',meta.github)}</div></div>${orgStatGrid(o)}<div class="card"><b>创始人 / 核心团队</b><div class="founders">${founderCards(o,meta)}</div><div class="source-note">已授权照片优先显示；未确认版权或身份的人物使用 portrait pack v2 安全头像。</div></div><div class="card"><b>代表模型</b><div class="models-grid">${o.models.map((m,i)=>{const c=o.cats[i%o.cats.length]||'General';const mm=modelObject(o,i);const md=getModelMeta(mm);return `<div class="model-chip model-info-chip" onclick="focusModelFromDetail('${o.id}',${i})"><i style="background:${categoryColor(c,o.type)};color:${categoryColor(c,o.type)}"></i><b>${esc(m)}</b><span class="muted">${esc(modelMiniSummary(mm,o,md))}</span>${modelCardLinks(md)}</div>`}).join('')}</div></div>`}
function renderDetailModel(m,o){const meta=getModelMeta(m);const orgMeta=getDisplayOrgMeta(o);const related=getRelatedModelsByPaper(m);const paperLinks=[linkBtn('Paper / Card',meta.paperUrl),linkBtn('Hugging Face',meta.hf),linkBtn('Model Page',meta.modelUrl),linkBtn('Company Website',orgMeta.website)].filter(Boolean).join('');document.getElementById('detail').innerHTML=`<h3>Model Node / 模型节点</h3>${detailTrail(['World',countryLabel(m.country),m.org,m.name])}<div class="org-hero compact">${orgLogoTag(o,orgMeta)}<div><h2>${esc(m.name)}</h2><p class="muted">${esc(m.org)} · ${esc(m.city)}, ${countryLabel(m.country)}</p></div></div><div class="badges"><span class="badge">${categoryLabel(m.cat)}</span><span class="badge">${typeLabel(m.type)}</span><span class="badge">${tierLabel(m.tier)}</span></div><div class="card"><b>模型信息</b><p>${esc(modelSummary(m,o,meta))}</p>${paperLinks?`<div class="link-row">${paperLinks}</div>`:''}</div><div class="card paper-box"><b class="paper-title">${related.length?'同源模型关系':'模型关系'}</b>${related.length?`<p class="muted">这些模型关联到同一组论文、系统卡或官方资料，选中当前模型时地图会显示关系线。</p><div class="related-list">${related.map(r=>`<span class="related-pill" onclick="focusModelFromDetail('${r.orgId}',${r.index})">${esc(r.name)} · ${esc(r.org)}</span>`).join('')}</div>`:`<p class="muted">当前模型以独立模型族展示，可从公司视角继续比较同机构模型。</p>`}</div><div class="card"><b>所属公司</b><p>${esc(orgMeta.about)}</p><div class="link-row">${linkBtn('Company Website',orgMeta.website)}</div></div><div class="card"><b>同机构模型</b><p>${o.models.map(esc).join(' · ')}</p></div>`}
function peopleStrip(o,meta=getDisplayOrgMeta(o)){return `<div class="people-strip">${meta.founders.slice(0,2).map(f=>`<span><b>${esc(f.name)}</b><small>${esc(f.role||'核心团队')}</small></span>`).join('')}</div>`}
function renderDetailOrg(o){const meta=getDisplayOrgMeta(o);document.getElementById('detail').innerHTML=`<h3>Company Anchor / 公司锚点</h3>${detailTrail(['World',countryLabel(o.country),o.name])}<div class="org-hero">${orgLogoTag(o,meta)}<div><h2>${esc(o.name)}</h2><p class="muted">${esc(o.city)}, ${countryLabel(o.country)}</p></div></div><div class="badges"><span class="badge">${typeLabel(o.type)}</span><span class="badge">${tierLabel(o.tier)}</span><span class="badge">${o.models.length} models</span>${[...new Set(o.cats)].slice(0,5).map(c=>`<span class="badge">${categoryLabel(c)}</span>`).join('')}</div>${peopleStrip(o,meta)}<div class="card"><b>公司画像</b><p>${esc(meta.about)}</p><div class="link-row">${linkBtn('Company Website',meta.website)}${linkBtn('HF Org',meta.hf)}${linkBtn('GitHub',meta.github)}</div></div>${orgStatGrid(o)}<div class="card"><b>创始人 / 核心团队</b><div class="founders">${founderCards(o,meta)}</div><div class="source-note">已授权照片优先显示；未确认版权或身份的人物使用 portrait pack v2 安全头像。</div></div><div class="card"><b>代表模型</b><div class="models-grid">${o.models.map((m,i)=>{const c=o.cats[i%o.cats.length]||'General';const mm=modelObject(o,i);const md=getModelMeta(mm);return `<div class="model-chip model-info-chip" onclick="focusModelFromDetail('${o.id}',${i})"><i style="background:${categoryColor(c,o.type)};color:${categoryColor(c,o.type)}"></i><b>${esc(m)}</b><span class="muted">${esc(modelMiniSummary(mm,o,md))}</span>${modelCardLinks(md)}</div>`}).join('')}</div></div>`}
function drawBackground(t){ctx.clearRect(0,0,W,H);const theme=THEMES[currentTheme]||THEMES.nebula;const stops=theme.canvas||THEMES.nebula.canvas;const g=ctx.createRadialGradient(W*.50,H*.42,0,W*.50,H*.42,Math.max(W,H)*.82);g.addColorStop(0,stops[1]);g.addColorStop(.46,stops[1]);g.addColorStop(1,stops[2]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);ctx.save();for(let si=0;si<stars.length;si++){if((perfMode&&si%2===0)||(!perfMode&&si%3===0))continue;const s=stars[si];const tw=.42+Math.sin(t*.001+s.p)*.24;ctx.globalAlpha=(s.c>.92?.42:.18)*tw;ctx.fillStyle=s.c>.84?'rgba(116,221,255,.78)':'rgba(215,228,255,.68)';const x=(s.x*W+camera.x*.010*s.r+W)%W;const y=(s.y*H+camera.y*.008*s.r+H)%H;ctx.beginPath();ctx.arc(x,y,s.r*.78,0,Math.PI*2);ctx.fill()}ctx.restore();ctx.save();ctx.globalAlpha=.055;ctx.strokeStyle='rgba(125,223,255,.16)';ctx.lineWidth=1;const gap=Math.max(26,44*camera.zoom);for(let x=(W/2+camera.x*.18)%gap;x<W;x+=gap){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,H);ctx.stroke()}for(let y=(H/2+camera.y*.18)%gap;y<H;y+=gap){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(W,y);ctx.stroke()}ctx.restore()}
function drawDensity(t){if(!densityMode)return;ctx.save();ctx.globalCompositeOperation='lighter';let idx=0;for(const o of ORGS){if(!passesOrg(o))continue;if(perfMode&&idx++%2)continue;const p=project(o.lng,o.lat);const intensity=(o.models.length/10+.55)*(o.tier==='frontier'?1.12:1);const r=(22+o.models.length*5.4)*camera.zoom*intensity;const col=o.type==='Open'?COLORS.Open:o.type==='Mixed'?COLORS.Multimodal:COLORS.General;const rgb=hexToRgb(col);const g=ctx.createRadialGradient(p.x,p.y,0,p.x,p.y,r);g.addColorStop(0,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.14)`);g.addColorStop(.30,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.055)`);g.addColorStop(.78,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},.012)`);g.addColorStop(1,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},0)`);ctx.fillStyle=g;ctx.beginPath();ctx.arc(p.x,p.y,r,0,Math.PI*2);ctx.fill()}ctx.restore()}
function drawClouds(t){if(!densityMode)return;ctx.save();ctx.globalCompositeOperation='lighter';const z=camera.zoom;for(let ci=0;ci<clouds.length;ci++){if((perfMode&&ci%3!==0)||(!perfMode&&ci%2!==0))continue;const p0=clouds[ci];const o=ORGS[p0.oi];if(!passesOrg(o))continue;const cat=p0.cat;if(active!=='All'&&active!=='Open'&&cat!==active&&!(active==='Open'&&(cat==='Open'||o.type==='Open')))continue;const op=project(o.lng,o.lat);const a=p0.angle+Math.sin(t*.00034+p0.phase)*.055+p0.spin*t*.66;const scale=z*(z<1?0.78:.88);const x=op.x+Math.cos(a)*p0.radius*scale;const y=op.y+Math.sin(a)*p0.radius*.62*scale+(seeded(p0.oi*99+p0.mi)*5-2.5)*scale;if(x<-80||x>W+80||y<-80||y>H+80)continue;const col=categoryColor(cat,o.type);const rgb=hexToRgb(col);let alpha=p0.alpha*(z<1.1?.30:.24);if(selected){if(selected.kind==='org'&&selected.data.id!==o.id)alpha*=.22;if(selected.kind==='country'&&selected.data.country!==o.country)alpha*=.26}ctx.fillStyle=`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${alpha})`;ctx.strokeStyle=ctx.fillStyle;const size=p0.size*(z<1?.88:Math.min(1.85,z*.68));if(p0.shape==='tri'){ctx.beginPath();ctx.moveTo(x,y-size*1.7);ctx.lineTo(x+size*1.55,y+size*1.3);ctx.lineTo(x-size*1.55,y+size*1.3);ctx.closePath();ctx.fill()}else if(p0.shape==='dash'){ctx.lineWidth=Math.max(.65,size*.54);ctx.beginPath();ctx.moveTo(x-size*1.7,y);ctx.lineTo(x+size*1.7,y+size*.55);ctx.stroke()}else{ctx.beginPath();ctx.arc(x,y,size,0,Math.PI*2);ctx.fill()}}ctx.restore()}
function drawGlow(x,y,r,color,alpha=.2){const rgb=hexToRgb(color);ctx.save();ctx.globalCompositeOperation='lighter';const rr=r*(perfMode?.58:.70);const aa=Math.min(alpha*(perfMode?.40:.52),.12);const g=ctx.createRadialGradient(x,y,0,x,y,rr);g.addColorStop(0,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${aa})`);g.addColorStop(.38,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},${aa*.28})`);g.addColorStop(1,`rgba(${rgb[0]},${rgb[1]},${rgb[2]},0)`);ctx.fillStyle=g;ctx.beginPath();ctx.arc(x,y,rr,0,Math.PI*2);ctx.fill();ctx.restore()}
function render(t=0){if(!pageVisible){lastT=0;return}if(perfMode&&lastT&&t-lastT<32){requestAnimationFrame(render);return}if(lastT){const dt=t-lastT;fps=fps*.92+(1000/Math.max(16,dt))*.08}lastT=t;if(t-lastFpsUpdate>680){const f=document.getElementById('fpsMeter');if(f)f.textContent=Math.round(fps)+' FPS · '+(perfMode?'省电':'高画质');lastFpsUpdate=t}smooth();drawBackground(t);drawGraticule();drawCountries();drawDensity(t);drawFlows(t);drawPaperLinks(t);drawOrgPaperLinks(t);drawClouds(t);drawMiniTiles(t);drawNodes(t);drawSelection();drawTooltip();requestAnimationFrame(render)}
const detailScrollPane=document.getElementById('detail');if(detailScrollPane){new MutationObserver(()=>{detailScrollPane.scrollTop=0}).observe(detailScrollPane,{childList:true})}
document.getElementById('search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();renderCountryList();if(query.length>=2){const m=allModels.find(x=>x.name.toLowerCase().includes(query));if(m){const o=getOrgById(m.orgId);selected={kind:'model',data:m};flyTo(m.lng,m.lat,3.05);renderDetailModel(m,o);return}const o=ORGS.find(x=>(x.name+' '+countryLabel(x.country)+' '+x.city).toLowerCase().includes(query));if(o){selected={kind:'org',data:o};flyTo(o.lng,o.lat,2.55);renderDetailOrg(o)}}});
document.getElementById('homeBtn').onclick=()=>{selected=null;query='';const search=document.getElementById('search');if(search)search.value='';camera.targetZoom=1.05;camera.targetX=0;camera.targetY=10;renderCountryList();renderDefaultDetail();toast('已回到全球视角')};
document.getElementById('randomBtn').onclick=()=>{const arr=ORGS.filter(passesOrg);const o=arr[Math.floor(Math.random()*arr.length)]||ORGS[0];selected={kind:'org',data:o};flyTo(o.lng,o.lat,2.85);renderDetailOrg(o);toast('随机飞行：'+o.name)};
function updateControls(){const pairs=[['densityBtn',densityMode],['flowBtn',flowMode],['labelsBtn',labelsMode]];for(const [id,on] of pairs){const b=document.getElementById(id);if(b){b.className='btn '+(on?'on':'off')}}const q=document.getElementById('qualityBtn');if(q){q.className='btn '+(!perfMode?'on':'off');q.textContent=!perfMode?'高画质':'省电'}}
document.getElementById('densityBtn').onclick=()=>{densityMode=!densityMode;updateControls();toast(densityMode?'密度/星云已开启':'密度/星云已关闭')};
document.getElementById('flowBtn').onclick=()=>{flowMode=!flowMode;updateControls();toast(flowMode?'流光关系线已开启':'流光关系线已关闭')};
document.getElementById('labelsBtn').onclick=()=>{labelsMode=!labelsMode;updateControls();toast(labelsMode?'标签已显示':'标签已隐藏')};
document.getElementById('qualityBtn').onclick=()=>{qualityMode=qualityMode==='high'?'low':'high';perfMode=(qualityMode==='low');localStorage.setItem('worldroadmap-quality',qualityMode);clouds=makeCloudParticles();lastT=0;resize();updateControls();toast(qualityMode==='high'?'高画质模式':'省电模式：减少粒子与像素压力')};
document.addEventListener('keydown',e=>{if(e.target&&/input|select|textarea/i.test(e.target.tagName))return;const k=e.key.toLowerCase();if(k==='escape'){closeFounderModal();selected=null;renderCountryList();renderDefaultDetail();toast('已清除选择')}if(k==='/'){e.preventDefault();const search=document.getElementById('search');if(search){search.focus();search.select()}}if(k==='h')document.getElementById('homeBtn').click();if(k==='d')document.getElementById('densityBtn').click();if(k==='l')document.getElementById('labelsBtn').click();if(k==='f')document.getElementById('flowBtn').click();if(k==='p')document.getElementById('qualityBtn').click();if(k==='r')document.getElementById('randomBtn').click()});
document.getElementById('modalClose').onclick=closeFounderModal;document.getElementById('modalBackdrop').onclick=closeFounderModal;renderThemeSelect();renderStats();renderCountryList();renderFilters();updateControls();renderDefaultDetail();requestAnimationFrame(render);
